schema_ddl:
CREATE TABLE magazzini (
    magazzino_id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome TEXT NOT NULL,
    citta TEXT NOT NULL,
    capacita_m3 NUMERIC(10,2) NOT NULL CHECK (capacita_m3 > 0)
);

CREATE TABLE prodotti (
    prodotto_id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome TEXT NOT NULL,
    categoria TEXT NOT NULL,
    peso_kg NUMERIC(8,2) NOT NULL CHECK (peso_kg > 0)
);

CREATE TABLE giacenze (
    magazzino_id INT NOT NULL REFERENCES magazzini(magazzino_id),
    prodotto_id INT NOT NULL REFERENCES prodotti(prodotto_id),
    quantita INT NOT NULL CHECK (quantita >= 0),
    data_rilevazione DATE NOT NULL DEFAULT CURRENT_DATE,
    PRIMARY KEY (magazzino_id, prodotto_id)
);

CREATE TABLE spedizioni (
    spedizione_id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    magazzino_id INT NOT NULL REFERENCES magazzini(magazzino_id),
    data_spedizione DATE NOT NULL,
    vettore TEXT NOT NULL,
    stato TEXT NOT NULL CHECK (stato IN ('in_attesa', 'in_transito', 'consegnata', 'annullata'))
);
